import pytest


def config_value(text: str, key: str) -> str:
    """Return the value for `key` in a `name=value` per-line config text.

    Each line is split on its first "=", so values may themselves contain
    "=". Whitespace around the name and around the value is stripped, and
    `key` is compared to the stripped name exactly (case-sensitive).
    Blank lines, lines starting with "#" (after stripping), and lines
    without "=" are ignored. If the key appears more than once, the first
    occurrence wins. Returns "" when the key is absent or its value is
    empty. Never reads files; only `text` is consulted.
    """
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        name, sep, val = line.partition("=")
        if not sep:
            continue
        if name.strip() == key:
            return val.strip()
    return ""


def test_basic_lookup() -> None:
    assert config_value("a=1\nb=2", "b") == "2"
    assert config_value("a=1\nb=2", "a") == "1"


def test_missing_key_returns_empty() -> None:
    assert config_value("a=1", "z") == ""


def test_empty_text() -> None:
    assert config_value("", "a") == ""


def test_whitespace_stripped() -> None:
    assert config_value("  name  =  hello world  \n", "name") == "hello world"


def test_value_contains_equals() -> None:
    assert config_value("url=http://x/?a=b", "url") == "http://x/?a=b"


def test_empty_value() -> None:
    assert config_value("a=\nb=2", "a") == ""


def test_comments_and_blank_lines_ignored() -> None:
    text = "# a=hidden\n\n   # a=also hidden\na=real\n"
    assert config_value(text, "a") == "real"
    assert config_value("# a=1", "a") == ""


def test_lines_without_equals_ignored() -> None:
    assert config_value("junk\na=1", "junk") == ""
    assert config_value("junk\na=1", "a") == "1"


def test_duplicate_key_first_wins() -> None:
    assert config_value("a=1\na=2", "a") == "1"


def test_key_is_case_sensitive() -> None:
    assert config_value("Key=1", "key") == ""
    assert config_value("Key=1", "Key") == "1"


def test_key_must_match_exactly_not_as_prefix() -> None:
    assert config_value("abc=1", "ab") == ""
    assert config_value("ab=1\nabc=2", "abc") == "2"


def test_crlf_line_endings() -> None:
    assert config_value("a=1\r\nb=2\r\n", "b") == "2"


@pytest.mark.parametrize(
    ("text", "key", "expected"),
    [
        ("a=1", "a", "1"),
        (" a = 1 ", "a", "1"),
        ("a=1=2", "a", "1=2"),
        ("=5", "", "5"),
        ("a=1", "", ""),
    ],
)
def test_parametrized(text: str, key: str, expected: str) -> None:
    assert config_value(text, key) == expected

